عالٍ","ماجستير","دكتوراه"],"maxItems":7,"criterionShape":"values","allowExclude":true},{"fieldId":"partnerCriteria.profession","kind":"criterion","options":["الطب والرعاية الصحية","الهندسة والعمارة","التقنية والبرمجة","التعليم والتدريب","البحث والعمل الأكاديمي","الإدارة والموارد البشرية","المال والمحاسبة","القانون والاستشارات","التجارة والمبيعات","التسويق والإعلام","التصميم والفنون","الترجمة واللغات","القطاع العسكري والأمني","الخدمات الحكومية","النقل والخدمات اللوجستية","السياحة والضيافة","الصناعة والحرف","الزراعة والبيئة","العمل الاجتماعي وغير الربحي","مجال مهني آخر","أعمال حرة وريادة أعمال","عمل مستقل","طالب / طالبة","متفرغ / متفرغة للمنزل","باحث / باحثة عن عمل","متقاعد / متقاعدة","لا أعمل حاليًا"],"maxItems":27,"criterionShape":"values","allowExclude":true},{"fieldId":"partnerCriteria.maritalStatus","kind":"criterion","options":["never_married","divorced","widowed","married"],"maxItems":4,"criterionShape":"values","allowExclude":true},{"fieldId":"partnerCriteria.dressStyle","kind":"criterion","options":["hijab","niqab","uncovered"],"maxItems":3,"criterionShape":"values","allowExclude":true},{"fieldId":"partnerCriteria.children","kind":"criterion","options":["none","any"],"criterionShape":"target"},{"fieldId":"partnerCriteria.smoking","kind":"criterion","options":["never"],"criterionShape":"target"},{"fieldId":"partnerCriteria.dressFlexibility","kind":"criterion","options":["open_to_discussion","open_to_change"],"criterionShape":"target"},{"fieldId":"partnerCriteria.tribalBackground","kind":"criterion","options":["tribal","non_tribal","same_tribe"],"criterionShape":"target"},{"fieldId":"partnerCriteria.skinTone","kind":"criterion","options":["tone_1","tone_2","tone_3","tone_4","tone_5","tone_6","tone_7","tone_8"],"maxItems":8,"criterionShape":"values","allowExclude":true}]'::jsonb) where value->>'fieldId'=item->>'fieldId';
 if field is null or jsonb_typeof(item->'values') is distinct from 'array' or jsonb_array_length(item->'values')>coalesce((field->>'maxItems')::int,30)
  or jsonb_typeof(item->'exclude') is distinct from 'boolean' then return false;end if;
 criterion:=field->>'kind' in ('criterion','range');
 if criterion then
  if coalesce(item->>'mode','') not in ('any','prefer','require') then return false;end if;
 else if item->'mode' is distinct from 'null'::jsonb or item->'exclude'='true'::jsonb then return false;end if;end if;
 if item->'exclude'='true'::jsonb and coalesce(field->>'allowExclude','false')<>'true' then return false;end if;
 if criterion and item->>'mode'='any' then return item->'values'='[]'::jsonb and item->'exclude'='false'::jsonb;end if;
 if field->>'criterionShape'='mode' then return item->'values'='[]'::jsonb and item->'exclude'='false'::jsonb;end if;
 if jsonb_array_length(item->'values')<1 then return false;end if;
 if field->>'kind'<>'range' and (select count(*) from jsonb_array_elements(item->'values'))<>(select count(distinct value) from jsonb_array_elements(item->'values')) then return false;end if;
 if (field->>'kind' in ('text','number','enum') or field->>'criterionShape'='target') and jsonb_array_length(item->'values')<>1 then return false;end if;
 for v in select value from jsonb_array_elements(item->'values') loop
  if jsonb_typeof(v)<>'string' or length(v#>>'{}')>coalesce((field->>'maxLength')::int,1200) then return false;end if;
  if field->>'kind' in ('number','range') then
   if field->>'kind'='range' and v#>>'{}'='' then continue;end if;
   if (v#>>'{}')!~'^[0-9]{1,3}$' or (v#>>'{}')::int<(field->>'min')::int or (v#>>'{}')::int>(field->>'max')::int then return false;end if;
  elsif length(btrim(v#>>'{}'))=0 or (v#>>'{}')~*'https?://|www[.]' then return false;
  elsif field ? 'options' and not exists(select 1 from jsonb_array_elements(field->'options') o where o=v) then return false;end if;
 end loop;
 if field->>'kind'='range' then
  if jsonb_array_length(item->'values')<>2 or item->'values'='["",""]'::jsonb then return false;end if;
  if item#>>'{values,0}'<>'' and item#>>'{values,1}'<>'' and (item#>>'{values,0}')::int>(item#>>'{values,1}')::int then return false;end if;
 end if;
 if item->'exclude'='true'::jsonb and item->>'fieldId'<>'partnerCriteria.nationality' and jsonb_array_length(item->'values')>=jsonb_array_length(field->'options') then return false;end if;
 return true;
 exception when others then return false;end $$;
revoke all on function marriage.interview_profile_values_valid(jsonb) from public,anon,authenticated,service_role;

-- The new optional keys are checked below; all original document checks stay intact.
do $keys$ declare definition text;updated text;begin
 definition:=pg_get_functiondef('marriage.interview_document_valid_before_required(jsonb)'::regprocedure);
 updated:=replace(definition,'''draftAnswer'',''reviewSharing'',''confirmedAt''))','''draftAnswer'',''reviewSharing'',''confirmedAt'',''profileProposals'',''profileConfirmed'',''profileContext'',''assessmentContext''))');
 if updated=definition then raise exception 'Expected interview document whitelist missing';end if;execute updated;
end $keys$;

create or replace function marriage.interview_evidence_valid(doc jsonb,evidence jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
declare e jsonb;begin
 if jsonb_typeof(evidence) is distinct from 'array' or jsonb_array_length(evidence) not between 1 and 3 then return false;end if;
 for e in select value from jsonb_array_elements(evidence) loop
  if jsonb_typeof(e) is distinct from 'object' or not(e ?& array['turnId','quote']) or exists(select 1 from jsonb_object_keys(e) k where k not in ('turnId','quote'))
   or jsonb_typeof(e->'turnId') is distinct from 'string' or length(e->>'turnId') not between 1 and 100
   or jsonb_typeof(e->'quote') is distinct from 'string' or length(btrim(e->>'quote')) not between 1 and 240 then return false;end if;
  if left(e->>'turnId',8)='context:' then
   if not exists(select 1 from jsonb_array_elements(coalesce(doc->'assessmentContext','[]')) c where 'context:'||(c->>'id')=e->>'turnId' and replace((c->'values')::text,' ','')=e->>'quote') then return false;end if;
  elsif not exists(select 1 from jsonb_array_elements(doc->'turns') t where t->>'id'=e->>'turnId' and t->'skipped'='false'::jsonb and strpos(t->>'answer',e->>'quote')>0) then return false;end if;
 end loop;return true;
 exception when others then return false;end $$;
revoke all on function marriage.interview_evidence_valid(jsonb,jsonb) from public,anon,authenticated,service_role;

alter function marriage.interview_document_valid(jsonb) rename to interview_document_valid_before_profile_capture;
create function marriage.interview_document_valid(doc jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
declare arr text;p jsonb;field jsonb;begin
 if not marriage.interview_document_valid_before_profile_capture(doc) then return false;end if;
 if doc ? 'assessmentContext' then
  if jsonb_typeof(doc->'assessmentContext')<>'array' or jsonb_array_length(doc->'assessmentContext')>44 then return false;end if;
  if (select count(*) from jsonb_array_elements(doc->'assessmentContext'))<>(select count(distinct value->>'id') from jsonb_array_elements(doc->'assessmentContext')) then return false;end if;
  for p in select value from jsonb_array_elements(doc->'assessmentContext') loop
   if jsonb_typeof(p)<>'object' or not(p ?& array['id','values']) or exists(select 1 from jsonb_object_keys(p) k where k not in ('id','values')) then return false;end if;
   select value into field from jsonb_array_elements('[{"id":"preference:children_plan:self","values":["A","B","C"]},{"id":"preference:children_plan:partner","values":["A","B","C"]},{"id":"preference:residence_plan:self","values":["A","B","C"]},{"id":"preference:residence_plan:partner","values":["A","B","C"]},{"id":"preference:wife_work:self","values":["A","B","C"]},{"id":"preference:wife_work:partner","values":["A","B","C"]},{"id":"preference:marriage_timeline:self","values":["A","B","C","D"]},{"id":"preference:marriage_timeline:partner","values":["A","B","C","D"]},{"id":"preference:family_boundaries:self","values":["A","B","C"]},{"id":"preference:family_boundaries:partner","values":["A","B","C"]},{"id":"preference:shared_budget:self","values":["A","B","C"]},{"id":"preference:shared_budget:partner","values":["A","B","C"]},{"id":"preference:household_roles:self","values":["A","B","C"]},{"id":"preference:household_roles:partner","values":["A","B","C"]},{"id":"preference:weekly_planning:self","values":["A","B","C"]},{"id":"preference:weekly_planning:partner","values":["A","B","C"]},{"id":"preference:social_rhythm:self","values":["A","B","C"]},{"id":"preference:social_rhythm:partner","values":["A","B","C"]},{"id":"preference:conversation_initiative_preference:self","values":["A","B","C","D"]},{"id":"preference:conversation_initiative_preference:partner","values":["A","B","C","D"]},{"id":"preference:match_disagreement_style:self","values":["A","B","C","D"]},{"id":"preference:match_disagreement_style:partner","values":["A","B","C","D"]},{"id":"preference:repair_after_conflict:self","values":["A","B","C"]},{"id":"preference:repair_after_conflict:partner","values":["A","B","C"]},{"id":"preference:conversation_depth:self","values":["A","B"]},{"id":"preference:conversation_depth:partner","values":["A","B"]},{"id":"preference:closeness_pace:self","values":["A","B","C"]},{"id":"preference:closeness_pace:partner","values":["A","B","C"]},{"id":"preference:curiosity_style:self","values":["A","B","C"]},{"id":"preference:curiosity_style:partner","values":["A","B","C"]},{"id":"preference:early_openness:self","values":["A","B","C"]},{"id":"preference:early_openness:partner","values":["A","B","C"]},{"id":"personality:social_energy:self","values":["A","B","C","D","E"]},{"id":"personality:initiative:self","values":["A","B","C","D","E"]},{"id":"personality:depth:self","values":["A","B","C","D","E"]},{"id":"personality:openness:self","values":["A","B","C","D","E"]},{"id":"personality:closeness:self","values":["A","B","C","D","E"]},{"id":"personality:reassurance:self","values":["A","B","C","D","E"]},{"id":"personality:support:self","values":["A","B","C","D","E"]},{"id":"personality:planning:self","values":["A","B","C","D","E"]},{"id":"personality:novelty:self","values":["A","B","C","D","E"]},{"id":"personality:conflict_pace:self","values":["A","B","C","D","E"]},{"id":"personality:directness:self","values":["A","B","C","D","E"]},{"id":"personality:quiet_comfort:self","values":["A","B","C","D","E"]}]'::jsonb) where value->>'id'=p->>'id';
   if field is null or jsonb_typeof(p->'values')<>'array' or jsonb_array_length(p->'values')<>1 or not exists(select 1 from jsonb_array_elements(field->'values') v where v=p#>'{values,0}') then return false;end if;
  end loop;
 end if;
 foreach arr in array array['proposals','confirmed'] loop
  if exists(select 1 from jsonb_array_elements(doc->arr) p cross join lateral jsonb_array_elements(p->'evidence') e where left(e->>'turnId',8)='context:' and e->>'turnId'<>'context:'||(p->>'id')) then return false;end if;
  if arr='proposals' and exists(select 1 from jsonb_array_elements(doc->arr) p cross join lateral jsonb_array_elements(p->'evidence') e where left(e->>'turnId',8)='context:' and e->>'quote'<>replace((p->'values')::text,' ','')) then return false;end if;
 end loop;
 foreach arr in array array['profileProposals','profileConfirmed','profileContext'] loop
  if not(doc ? arr) then continue;end if;
  if jsonb_typeof(doc->arr)<>'array' or jsonb_array_length(doc->arr)>80 then return false;end if;
  if (select count(*) from jsonb_array_elements(doc->arr))<>(select count(distinct value->>'fieldId') from jsonb_array_elements(doc->arr)) then return false;end if;
  for p in select value from jsonb_array_elements(doc->arr) loop
   if jsonb_typeof(p)<>'object' or not(p ?& array['fieldId','values','mode','exclude']) or not marriage.interview_profile_values_valid(p) then return false;end if;
   if arr='profileContext' then
    if exists(select 1 from jsonb_object_keys(p) k where k not in ('fieldId','values','mode','exclude')) then return false;end if;
   else
    if not(p ?& array['id','summary','evidence','needsClarification']) or exists(select 1 from jsonb_object_keys(p) k where k not in ('id','fieldId','values','mode','exclude','summary','evidence','needsClarification'))
     or p->>'id' is distinct from 'profile:'||(p->>'fieldId') or jsonb_typeof(p->'summary')<>'string' or length(btrim(p->>'summary')) not between 1 and 240
     or jsonb_typeof(p->'needsClarification')<>'boolean' or not marriage.interview_evidence_valid(doc,p->'evidence')
     or exists(select 1 from jsonb_array_elements(p->'evidence') e where left(e->>'turnId',8)='context:') then return false;end if;
   end if;
  end loop;
 end loop;return true;
 exception when others then return false;end $$;
revoke all on function marriage.interview_document_valid(jsonb),marriage.interview_document_valid_before_profile_capture(jsonb) from public,anon,authenticated,service_role;
